#!/usr/bin/env node
import { cp, lstat, mkdir, readdir } from "node:fs/promises";
import { dirname, isAbsolute, join, relative, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

export const ENGINE = fileURLToPath(new URL("../engine/", import.meta.url));
const OMIT = new Set(["node_modules", ".next", "checks", ".git"]);

async function entries(root, prefix = "") {
  const result = [];
  for (const item of await readdir(join(root, prefix), { withFileTypes: true })) {
    if (OMIT.has(item.name)) continue;
    const name = join(prefix, item.name);
    if (item.isSymbolicLink()) throw new Error(`Engine contains a symbolic link: ${name}`);
    if (item.isDirectory()) result.push(...await entries(root, name));
    else if (item.isFile()) result.push(name);
    else throw new Error(`Engine contains an unsupported file: ${name}`);
  }
  return result.sort();
}

async function stat(path) {
  try { return await lstat(path); }
  catch (error) { if (["ENOENT", "ENOTDIR"].includes(error.code)) return null; throw error; }
}

function within(parent, child) {
  const rel = relative(parent, child);
  return rel === "" || (!rel.startsWith("..") && !isAbsolute(rel));
}

/** Preflight every destination before writing any file. Existing story notes are kept. */
export async function scaffold(folder, { source = ENGINE } = {}) {
  const destination = resolve(folder);
  const engine = resolve(source);
  if (within(engine, destination) || within(destination, engine)) {
    throw new Error("The destination and engine source must be separate directories");
  }
  const files = await entries(engine);
  const conflicts = new Set();
  for (const file of files) {
    const target = join(destination, file);
    if (await stat(target)) conflicts.add(file);
    let parent = dirname(target);
    while (true) {
      const info = await stat(parent);
      if (info && (!info.isDirectory() || info.isSymbolicLink())) {
        conflicts.add(relative(destination, parent) || ".");
      }
      const next = dirname(parent);
      if (next === parent) break;
      parent = next;
    }
  }
  if (conflicts.size) return { copied: [], conflicts: [...conflicts].sort() };
  for (const file of files) {
    await mkdir(dirname(join(destination, file)), { recursive: true });
    await cp(join(engine, file), join(destination, file), { force: false, errorOnExist: true });
  }
  return { copied: files, conflicts: [] };
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  const args = process.argv.slice(2);
  const usage = "Usage: node scaffold.mjs <folder>\n       node scaffold.mjs --help\n\nCopies the engine without overwriting existing files.\nUse ./ before a folder name that begins with a dash.";
  const folder = args[0];
  if (args.length === 1 && ["--help", "-h"].includes(folder)) {
    console.log(usage);
  } else if (!folder || args.length !== 1 || folder.startsWith("-")) {
    if (folder?.startsWith("-") && !["--help", "-h"].includes(folder)) console.error(`Unknown option: ${folder}`);
    console.error(usage);
    process.exitCode = 2;
  } else {
    try {
      const result = await scaffold(folder);
      if (result.conflicts.length) {
        console.error(`Nothing written. These paths already exist or cannot be written safely:\n${result.conflicts.join("\n")}`);
        process.exitCode = 1;
      } else console.log(`Copied ${result.copied.length} engine files to ${resolve(folder)}`);
    } catch (error) { console.error(error.message); process.exitCode = 1; }
  }
}
@import "tailwindcss";
@import "../components/story/story.css";
:root { font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
* { box-sizing: border-box; }
body { margin: 0; }
a { color: inherit; }
button, select { font: inherit; }
import type { Metadata } from "next";
import { copy } from "@/content/copy";
import "./globals.css";

export const metadata: Metadata = copy.metadata;
export default function RootLayout({ children }: { children: React.ReactNode }) {
  return <html lang={copy.lang}><body>{children}</body></html>;
}

export const copy = {
  lang: "en",
  metadata: { title: "Storyfolio | Placeholder", description: "A placeholder page that tests the Storyfolio scroll engine." },
  railLabel: "Chapters",
  lookLabel: "Appearance",
  fpsLabel: "Frames per second",
  skipLabel: "Skip to the ending",
  backLabel: "Back to the start",
  pictureAlt: "A sheet marked as a chapter's picture, a static version of the scene.",
  faceWords: "Its picture",
  beats: {
    "opening.one": {
      title: "A placeholder, not a design.",
      body: "This page tests the engine. Replace every file in content/ with the person's story, each chapter's scene a picture of what it is about.",
      note: "The sheet stays where it is and shows a different picture in each chapter.",
    },
    "middle.one": {
      title: "A chapter's own shape.",
      body: "A line arrives with this chapter, loaded only when you come near it, and the sheet shows a picture from a file.",
      note: "This tests a chapter's extra shape. The text and the flat illustration also explain it without a canvas.",
    },
    "close.one": {
      title: "Readable without the scene.",
      body: "The text and its links stay readable when the scene cannot run.",
      note: "The link on the sheet is an ordinary keyboard-accessible link. The same destination is here in the text.",
    },
  },
};
import { Chapter, Beat, Kicker, Title, Body, Note } from "@/components/story/chapter";
import { Experience } from "@/content/experience";
import { story } from "@/content/story";
import { copy } from "@/content/copy";

export default function Home() {
  return <main><a className="story-skip" href="#close">{copy.skipLabel}</a><Experience>
    {story.chapters.map((chapter, index) => <Chapter key={chapter.id} id={chapter.id}>
      {chapter.beats.map((beat, beatIndex) => {
        const words = copy.beats[beat.id];
        return <Beat key={beat.id} story={story} id={beat.id} fallback={index === 1 ?
          // A local SVG is already sized; no image optimizer or network is needed.
          // eslint-disable-next-line @next/next/no-img-element
          <img src="/plain/face.svg" width="448" height="608" alt={copy.pictureAlt} /> : undefined}>
          <Kicker number={chapter.number}>{chapter.name}</Kicker>
          <Title id={`${beatIndex === 0 ? chapter.id : beat.id}-title`} as={index === 0 && beatIndex === 0 ? "h1" : "h2"}>{words.title}</Title>
          <Body>{words.body}</Body>
          <Note>{words.note}</Note>
          {index === 2 && <a href="#opening">{copy.backLabel}</a>}
        </Beat>;
      })}
    </Chapter>)}
  </Experience></main>;
}
